input.command:
cat > main.tf <<'EOF'
terraform {
  required_providers {
    local = {
      source  = "hashicorp/local"
      version = "~> 2.5"
    }
  }
}

# Supply via TF_VAR_log_shipper_key (or a secrets manager once the course gets to M06).
variable "log_shipper_key" {
  description = "AWS key for the sidecar that ships access logs to S3"
  type        = string
  sensitive   = true
}

resource "local_file" "log_shipper_env" {
  filename = "${path.module}/rendered/log-shipper.env"
  content  = "AWS_ACCESS_KEY_ID=${var.log_shipper_key}\n"
}
EOF
cat > shipper.tf <<'EOF'
# Supply via TF_VAR_shipper_access_key_id.
variable "shipper_access_key_id" {
  description = "AWS access key ID written into the log-shipper sidecar config"
  type        = string
  sensitive   = true
}

# Config file the log-shipper sidecar reads at boot.
resource "local_file" "shipper_config" {
  filename = "${path.module}/rendered/shipper.yaml"
  content  = <<-EOT
    region: ap-south-1
    bucket: kiranakart-access-logs
    access_key_id: ${var.shipper_access_key_id}
  EOT
}
EOF
checkov -d . --compact 2>&1 | grep -E "Passed|Failed|FAILED"; grep -rn AKIA . --exclude-dir=.git || echo "no AKIA in working tree"
(command -v terraform && terraform fmt -check && terraform init -backend=false -input=false >/dev/null && terraform validate) 2>&1 | tail -3

